/// T step, ket class (00): 1 nonzeros over 1 columns.
/// With FIRST, T is written instead of accumulated: the first chunk of every column starts
/// from zero (the same sums as accumulating into zeroed T), empty columns are zeroed.
/// # Safety
/// `cube` holds R up to la + lb + bra L; `e` the lane E nonzeros of one ket primitive;
/// `t` ncd x nhb vectors (column-major); `base` the cube offsets of the bra Hermite indices.
#[inline(always)]
pub unsafe fn tstep_00<V: Lanes, const FIRST: bool>(cube: *const V, base: &[u32], e: *const f64, t: *mut V) {
    let nhb = base.len();
    {
        let e0 = V::load8(&*(e.add(0 * 8) as *const [f64; 8]));
        let col = t.add(0 * nhb);
        for (rr, &b) in base.iter().enumerate() {
            let rp = cube.add(b as usize);
            let x = col.add(rr);
            let x0 = if FIRST { V::zero() } else { *x };
            let a0 = (*rp.add(0)).mul_add(e0, x0);
            *x = a0;
        }
    }
}

/// I step, bra class (00): 1 nonzeros over 1 rows, nhb = 1.
/// With FIRST, `out` is written instead of accumulated (first chunk of every row from zero,
/// empty rows zeroed).
/// # Safety
/// `t` ncd x nhb vectors (column-major), `eb` the bra E nonzeros of one primitive,
/// `out` nab x ncd vectors; columns cd0..cd1 are updated.
#[inline(always)]
pub unsafe fn istep_00<V: Lanes, const FIRST: bool>(t: *const V, eb: &[f64], out: *mut V, ncd: usize, cd0: usize, cd1: usize) {
    let eb = &eb[..1];
    {
        let b0 = V::splat(eb[0]);
        let orow = out.add(0 * ncd);
        for cd in cd0..cd1 {
            let tp = t.add(cd * 1);
            let x = orow.add(cd);
            let x0 = if FIRST { V::zero() } else { *x };
            let a0 = b0.mul_add(*tp.add(0), x0);
            *x = a0;
        }
    }
}

