        let e9 = V::load8(&*(e.add(739 * 8) as *const [f64; 8]));
        let e10 = V::load8(&*(e.add(894 * 8) as *const [f64; 8]));
        let e11 = V::load8(&*(e.add(934 * 8) as *const [f64; 8]));
        let col = t.add(0 * nhb);
        for (rr, &b) in base.iter().enumerate() {
            let rp = cube.add(b as usize);
            let x = col.add(rr);
            let x0 = if FIRST { V::zero() } else { *x };
            let a0 = (*rp.add(0)).mul_add(e0, x0);
            let a1 = *rp.add(293) * e1;
            let a0 = (*rp.add(52)).mul_add(e2, a0);
            let a1 = (*rp.add(586)).mul_add(e3, a1);
            let a0 = (*rp.add(345)).mul_add(e4, a0);
            let a1 = (*rp.add(104)).mul_add(e5, a1);
            let a0 = (*rp.add(879)).mul_add(e6, a0);
            let a1 = (*rp.add(638)).mul_add(e7, a1);
            let a0 = (*rp.add(397)).mul_add(e8, a0);
            let a1 = (*rp.add(156)).mul_add(e9, a1);
            let a0 = (*rp.add(1172)).mul_add(e10, a0);
            let a1 = (*rp.add(931)).mul_add(e11, a1);
            *x = a0 + a1;
        }
